begin; select set_config('request.jwt.claim.sub',(select id::text from auth.users where email='kg8460055@gmail.com'),true); select set_config('request.jwt.claims',(select jsonb_build_object('sub',id,'email',email,'role','authenticated')::text from auth.users where email='kg8460055@gmail.com'),true); do $$ declare r integer; p text:=gen_random_uuid()::text; begin if not public.dueno_permitido_v53('karen-shop') or public.dueno_permitido_v53('shopping-morales') or public.dueno_permitido_v53('el-titan-de-las-pinturas') then raise exception 'Permisos incorrectos';end if; select revision into r from public.piloto_menus_completos where slug='karen-shop'; perform public.catalogo_visual_modelo_guardar('karen-shop',r,p,jsonb_build_object('nombre','Prenda de prueba transaccional','precio',null,'seccion','Prueba SQL','ingredientes','','disponible',true,'fichaAvanzada','{"activa":true,"fotos":[],"secciones":[]}'::jsonb)); select revision into r from public.piloto_menus_completos where slug='karen-shop'; perform public.catalogo_seccion_administrar('karen-shop',r,'renombrar','Prueba SQL','Prueba nueva'); if not exists(select 1 from public.menu_productos_publicados where negocio='karen-shop' and producto=p and contenido->>'seccion'='Prueba nueva') then raise exception 'No renombró publicación';end if; select revision into r from public.piloto_menus_completos where slug='karen-shop'; perform public.catalogo_seccion_administrar('karen-shop',r,'ordenar','Prueba nueva',null,0); select revision into r from public.piloto_menus_completos where slug='karen-shop'; perform public.catalogo_seccion_administrar('karen-shop',r,'ocultar','Prueba nueva'); select revision into r from public.piloto_menus_completos where slug='karen-shop'; perform public.catalogo_seccion_administrar('karen-shop',r,'mostrar','Prueba nueva'); begin perform public.catalogo_seccion_administrar('shopping-morales',1,'crear','No permitido'); raise exception 'Acceso indebido'; exception when insufficient_privilege then null; end; end $$; rollback;
